insert into public.prayers (id, name, request, category, is_public, status, prayed_count, created_at, approved_at) values
  ('11111111-1111-4111-8111-000000000001', 'Margaret', 'Please pray for my husband Tom. He has heart surgery on Thursday and we are both scared. Pray for steady hands for the surgeons and peace for our family while we wait.', 'Health', true, 'approved', 41, now() - interval '1 days' - interval '37 minutes', now() - interval '1 days' - interval '37 minutes'),
  ('11111111-1111-4111-8111-000000000002', 'Anonymous', 'I have been waking up at 3 a.m. every night with my heart racing. I know God is with me but my mind will not rest. Please pray for peace and for sleep.', 'Anxiety and Peace', true, 'approved', 27, now() - interval '2 days' - interval '74 minutes', now() - interval '2 days' - interval '74 minutes'),
  ('11111111-1111-4111-8111-000000000003', 'David', 'I lost my job last month after twelve years. I have two kids and the savings are running low. Pray that God opens the right door and that I trust Him while I wait.', 'Finances', true, 'approved', 19, now() - interval '3 days' - interval '111 minutes', now() - interval '3 days' - interval '111 minutes'),
  ('11111111-1111-4111-8111-000000000004', 'Linda', 'My daughter and I have not spoken in two years. I miss her every day. Please pray that God softens both our hearts and brings us back together.', 'Family', true, 'approved', 33, now() - interval '4 days' - interval '148 minutes', now() - interval '4 days' - interval '148 minutes'),
  ('11111111-1111-4111-8111-000000000005', 'Anonymous', 'My mother went home to be with the Lord last week. I know she is with Jesus, but the house is so quiet. Please pray for comfort for me and my brothers.', 'Grief', true, 'approved', 52, now() - interval '5 days' - interval '185 minutes', now() - interval '5 days' - interval '185 minutes'),
  ('11111111-1111-4111-8111-000000000006', 'James', 'I have been offered a job in another state. It would mean leaving our church and our friends. Please pray for wisdom and clear direction for my wife and me.', 'Direction', true, 'approved', 14, now() - interval '6 days' - interval '222 minutes', now() - interval '6 days' - interval '222 minutes'),
  ('11111111-1111-4111-8111-000000000007', 'Rosa', 'Please pray for my son Michael. He walked away from the faith in college. I believe God is still chasing him. Pray that he comes home to Jesus.', 'Salvation', true, 'approved', 38, now() - interval '8 days' - interval '296 minutes', now() - interval '8 days' - interval '296 minutes'),
  ('11111111-1111-4111-8111-000000000008', 'Anonymous', 'I have been sober for 90 days. Some days are harder than others. Please pray that I stay strong and keep leaning on God one day at a time.', 'Other', true, 'approved', 22, now() - interval '9 days' - interval '333 minutes', now() - interval '9 days' - interval '333 minutes'),
  ('11111111-1111-4111-8111-000000000009', 'Ruth', 'I start chemotherapy next week. Pray for strength for my body, few side effects, and that I would feel God close to me in the hard days.', 'Health', true, 'approved', 29, now() - interval '11 days' - interval '407 minutes', now() - interval '11 days' - interval '407 minutes'),
  ('11111111-1111-4111-8111-000000000010', 'Carlos', 'My wife and I are struggling in our marriage. We still love each other but we keep hurting each other. Pray that we would learn to forgive and put God at the center of our home.', 'Family', true, 'approved', 17, now() - interval '13 days' - interval '481 minutes', now() - interval '13 days' - interval '481 minutes'),
  ('11111111-1111-4111-8111-000000000011', 'Grace', 'I am graduating in the spring and I do not know what is next. Please pray that I follow where God is leading and not just what looks safe.', 'Direction', true, 'pending', 0, now() - interval '0 days' - interval '0 minutes', null),
  ('11111111-1111-4111-8111-000000000012', 'Anonymous', 'This is private. Please pray for me as I face a hard conversation with my doctor next week. I would rather not share the details publicly.', 'Anxiety and Peace', false, 'pending', 0, now() - interval '0 days' - interval '0 minutes', null)
insert into public.testimonies (id, name, prayed_for, answer, prayer_id, status, praise_count, created_at, approved_at) values
  ('22222222-2222-4222-8222-000000000001', 'Margaret', 'My husband''s heart surgery.', 'Tom came through surgery with no complications. The surgeon said it went better than expected. We felt your prayers in that waiting room. Thank You, Jesus.', '11111111-1111-4111-8111-000000000001', 'approved', 64, now() - interval '0 days' - interval '0 minutes', now() - interval '0 days' - interval '0 minutes'),
  ('22222222-2222-4222-8222-000000000002', 'Anonymous', 'A way to pay our rent after my hours were cut.', 'A neighbor I barely knew knocked on our door with an envelope. It covered the rent to the dollar. She said God put us on her heart. I cried the whole night.', null, 'approved', 31, now() - interval '7 days' - interval '259 minutes', now() - interval '7 days' - interval '259 minutes'),
  ('22222222-2222-4222-8222-000000000003', 'Peter', 'My brother to come back to church.', 'After ten years away, my brother walked into church with me on Easter Sunday. He has come every week since. God never gave up on him.', null, 'approved', 45, now() - interval '12 days' - interval '444 minutes', now() - interval '12 days' - interval '444 minutes'),
  ('22222222-2222-4222-8222-000000000004', 'Joy', 'Peace in the middle of panic attacks.', 'The panic attacks have not disappeared overnight, but they are fewer and softer. I pray Philippians 4:6-7 every morning now. God is teaching me to breathe and trust Him.', null, 'approved', 28, now() - interval '20 days' - interval '140 minutes', now() - interval '20 days' - interval '140 minutes'),
  ('22222222-2222-4222-8222-000000000005', 'Samuel', 'A new job after being laid off.', 'I got the call this morning. Full-time, better hours, and closer to home. I start Monday. Praise God!', null, 'pending', 0, now() - interval '0 days' - interval '0 minutes', null)
